:root {
  --deep: #012a4a;
  --deep2: #013a63;
  --mid: #0466c8;
  --light: #61a5c2;
  --foam: #d9f0ff;
  --sand: #fff8ec;
  --accent: #ff8c42;
  --text: #06283d;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Trebuchet MS', 'Segoe UI', Verdana, sans-serif;
  background: var(--sand);
  color: var(--text);
  line-height: 1.6;
  overflow-x: hidden;
}

/* Hero */
.hero {
  position: relative;
  background: linear-gradient(180deg, var(--deep) 0%, var(--deep2) 45%, var(--mid) 100%);
  color: var(--foam);
  padding-bottom: 60px;
  overflow: hidden;
}

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24px 6vw;
  flex-wrap: wrap;
  gap: 12px;
}

.brand {
  font-size: 1.3rem;
  font-weight: bold;
  letter-spacing: 0.5px;
}

.nav-links a {
  color: var(--foam);
  text-decoration: none;
  margin-left: 24px;
  font-weight: 600;
  opacity: 0.9;
  transition: opacity 0.2s;
}

.nav-links a:hover { opacity: 1; text-decoration: underline; }

.hero-content {
  text-align: center;
  padding: 60px 6vw 100px;
  position: relative;
  z-index: 2;
}

.hero-content h1 {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  margin-bottom: 16px;
  text-shadow: 0 4px 20px rgba(0,0,0,0.25);
}

.hero-content p {
  font-size: clamp(1rem, 2vw, 1.3rem);
  max-width: 600px;
  margin: 0 auto 32px;
  color: var(--foam);
  opacity: 0.95;
}

.cta {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  padding: 14px 32px;
  border-radius: 40px;
  text-decoration: none;
  font-weight: bold;
  font-size: 1.05rem;
  box-shadow: 0 6px 20px rgba(255,140,66,0.4);
  transition: transform 0.2s, box-shadow 0.2s;
}

.cta:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 26px rgba(255,140,66,0.5);
}

.wave-divider {
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 90px;
}

.wave-divider path { fill: var(--sand); }

/* Bubbles */
.bubbles {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.bubble {
  position: absolute;
  bottom: -50px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.85), rgba(255,255,255,0.1));
  animation: rise linear infinite;
}

@keyframes rise {
  0% { transform: translateY(0) translateX(0); opacity: 0.8; }
  100% { transform: translateY(-110vh) translateX(20px); opacity: 0; }
}

/* Activities */
.activities {
  padding: 40px 6vw 20px;
  text-align: center;
  position: relative;
  z-index: 1;
}

.activities h2, .tips h2 {
  font-size: 2.2rem;
  color: var(--deep2);
}

.section-sub {
  color: var(--mid);
  margin-bottom: 40px;
  font-size: 1.1rem;
}

.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 28px;
  text-align: left;
}

.card {
  background: #fff;
  border-radius: 18px;
  padding: 28px 24px;
  box-shadow: 0 8px 24px rgba(1,58,99,0.1);
  border: 1px solid rgba(4,102,200,0.08);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
  position: relative;
}

.card:hover {
  transform: translateY(-6px);
  box-shadow: 0 14px 32px rgba(1,58,99,0.18);
}

.card-emoji {
  font-size: 2.4rem;
  margin-bottom: 12px;
}

.card h3 {
  color: var(--deep2);
  margin-bottom: 10px;
  font-size: 1.25rem;
}

.card p {
  color: #33475b;
  font-size: 0.98rem;
}

.tag {
  display: inline-block;
  margin-top: 14px;
  background: var(--light);
  color: #fff;
  font-size: 0.75rem;
  font-weight: bold;
  letter-spacing: 0.5px;
  padding: 5px 12px;
  border-radius: 20px;
  text-transform: uppercase;
}

/* Tips */
.tips {
  background: linear-gradient(180deg, var(--sand), #eaf6ff);
  padding: 60px 6vw 80px;
  text-align: center;
}

.tip-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
  margin-top: 32px;
  max-width: 1100px;
  margin-left: auto;
  margin-right: auto;
}

.tip {
  background: rgba(255,255,255,0.7);
  border: 1px solid rgba(4,102,200,0.15);
  border-radius: 16px;
  padding: 24px;
  text-align: left;
}

.tip h4 {
  color: var(--deep2);
  margin-bottom: 8px;
}

.tip p {
  color: #33475b;
  font-size: 0.95rem;
}

/* Footer */
footer {
  position: relative;
  background: var(--deep);
  color: var(--foam);
  text-align: center;
  padding: 60px 6vw 30px;
}

.footer-wave {
  top: -88px;
}

.footer-wave path { fill: var(--deep); }

footer p {
  opacity: 0.85;
  font-size: 0.95rem;
}

@media (max-width: 600px) {
  .nav-links a { margin-left: 14px; font-size: 0.9rem; }
}

